    {
        Title="Captovix · Nền & mặt nạ";Width=Math.Min(980,SystemParameters.WorkArea.Width-32);Height=Math.Min(700,SystemParameters.WorkArea.Height-32);MinWidth=760;MinHeight=500;WindowStartupLocation=WindowStartupLocation.CenterOwner;ShowInTaskbar=false;SetResourceReference(StyleProperty,typeof(Window));var root=new Grid{Margin=new(16)};root.RowDefinitions.Add(new(){Height=GridLength.Auto});root.RowDefinitions.Add(new(){Height=new GridLength(1,GridUnitType.Star)});root.RowDefinitions.Add(new(){Height=GridLength.Auto});Content=root;
        var head=new StackPanel();head.Children.Add(new TextBlock{Text="Phục hồi nền màu phẳng",FontSize=21,FontWeight=FontWeights.SemiBold});head.Children.Add(new TextBlock{Text="Kéo thêm khung trên ảnh nguồn để giữ nguyên phần tử lân cận. Mặt nạ đứng yên ở vùng gốc, độc lập với đối tượng đã di chuyển/xóa.",TextWrapping=TextWrapping.Wrap,Margin=new(0,6,0,10)});var picker=new ComboBox{ItemsSource=patches.Select((p,i)=>$"Vùng {i+1} · {p.Bounds}").ToArray()};head.Children.Add(picker);var options=new WrapPanel();var color=new TextBox{Width=105,MaxLength=7};var choose=new Button{Content="Màu nền…"};var update=new Button{Content="Xem lại"};var add=new CheckBox{Content="Kéo vùng cần giữ",IsChecked=true,Margin=new(8)};var mask=new CheckBox{Content="Hiện mặt nạ",Margin=new(8)};options.Children.Add(color);options.Children.Add(choose);options.Children.Add(update);options.Children.Add(add);options.Children.Add(mask);head.Children.Add(options);var warning=new TextBlock{TextWrapping=TextWrapping.Wrap,Margin=new(0,6,0,8)};warning.SetResourceReference(TextBlock.ForegroundProperty,"Warning");head.Children.Add(warning);if(history is {Count:>0}){var journal=new Expander{Header="Thao tác gần đây",IsExpanded=false,Content=new TextBlock{Text=string.Join("\n",history.Reverse().Take(15).Select(x=>$"{x.At.ToLocalTime():dd/MM HH:mm:ss} · {x.Action}")),MaxHeight=100,TextWrapping=TextWrapping.Wrap}};head.Children.Add(journal);}root.Children.Add(head);
        var body=new Grid();body.ColumnDefinitions.Add(new());body.ColumnDefinitions.Add(new());Grid.SetRow(body,1);root.Children.Add(body);var surface=new ElementScanSurface{Ready=true,AddMode=true,FixedLabel="Giữ"};var sourceFrame=new ScrollViewer{Content=surface,HorizontalScrollBarVisibility=ScrollBarVisibility.Auto,VerticalScrollBarVisibility=ScrollBarVisibility.Auto,Margin=new(0,0,8,0)};body.Children.Add(sourceFrame);var right=new DockPanel();Grid.SetColumn(right,1);body.Children.Add(right);var list=new ListBox{Height=100,Margin=new(0,6,0,0)};DockPanel.SetDock(list,Dock.Bottom);right.Children.Add(list);var removeArea=new Button{Content="Bỏ vùng giữ đang chọn"};DockPanel.SetDock(removeArea,Dock.Bottom);right.Children.Add(removeArea);var after=new Image{Stretch=System.Windows.Media.Stretch.Uniform};right.Children.Add(after);
