        picker.SelectionChanged+=(_,_)=>{if(picker.SelectedIndex<0)return;current=patches[picker.SelectedIndex].Copy();var data=load(current);raw=data.Source;sampled=data.Sample;pixels=ImageTransfer.Bgra(raw);var b=current.Bounds;surface.Region=b;surface.Image=new CroppedBitmap(raw,new(b.X-sampled.X,b.Y-sampled.Y,b.Width,b.Height));surface.SetZoom(Math.Min(4,Math.Min(420d/b.Width,330d/b.Height)));keep=current.Protected.Select(x=>new ScanElement{Bounds=x,Kind=MockupKind.Block}).ToList();color.Text=current.Background;Preview();};
        surface.AddRequested+=r=>{if(keep.Count>=200){warning.Text="Tối đa200vùng giữ.";return;}keep.Add(new(){Bounds=r,Kind=MockupKind.Block});Preview();};surface.SelectRequested+=s=>{surface.Selected=s;list.SelectedIndex=s==null?-1:keep.IndexOf(s);};surface.Edited+=done=>{if(done)Preview();};list.SelectionChanged+=(_,_)=>{if(syncing)return;surface.Selected=list.SelectedIndex>=0?keep[list.SelectedIndex]:null;surface.InvalidateVisual();};removeArea.Click+=(_,_)=>{if(list.SelectedIndex>=0){keep.RemoveAt(list.SelectedIndex);surface.Selected=null;Preview();}};
        add.Click+=(_,_)=>surface.AddMode=add.IsChecked==true;update.Click+=(_,_)=>Preview();mask.Click+=(_,_)=>Preview();choose.Click+=(_,_)=>{var chosen=NativeColorPicker.Pick(this);if(chosen!=null){color.Text=chosen;Preview();}};save.Click+=(_,_)=>{Preview();if(save.IsEnabled)DialogResult=true;};erase.Click+=(_,_)=>{Remove=true;Result=current;DialogResult=true;};close.Click+=(_,_)=>DialogResult=false;picker.SelectedIndex=0;Closed+=(_,_)=>{surface.Image=null;after.Source=null;raw=null;pixels=null;};
